    /**
     * Save EULA acceptance.
     *
     * This function records acceptance of cPanel & WHM's legal terms. To do this, the function creates a touchfile in
     * the `/var/cpanel/activate/` directory and writes an acceptance audit record to
     * `/var/cpanel/activate/eula_acceptance.json`. The audit record captures the accepting user, timestamp, remote IP
     * address, agreement version, and agreement URLs.
     *
     * Documented: Available in cPanel and WHM 76 and later. Uses form POST with one request and no automatic retry or
     * rollback.
     *
     * Documented: Records acceptance of cPanel and WHM legal agreements, including an audit record of accepting user,
     * time, remote IP, agreement version and URLs. This is a legal acceptance action; API success reports that action,
     * not a review of the agreements.
     *
     * API-map identity: whm1:accept_eula#GET (wire name accept_eula; Updates).
     *
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/updates/eula-accept_eula
     */
    public function acceptEula(): void
    {
        ($this->run)(ServerSpec::ACCEPT_EULA, []);
    }

    /**
     * Add configuration cluster server.
     *
     * This function adds a server to a configuration cluster. The function's return data appears in the `metadata`
     * section of its output.
     *
     * Documented: Available in cPanel and WHM 11.44 and later. Uses form POST with one request and no automatic retry
     * or rollback.
     *
     * Documented: Run as a root-level account on the intended parent server. Cluster membership can be viewed and
     * modified only from that parent. Sends the remote access key as a sensitive form field over the configured HTTPS
     * transport; creates a remote cluster relationship. Result information is in responseMeta()->whm rather than a data
     * payload.
     *
     * API-map identity: whm1:add_configclusterserver#POST (wire name add_configclusterserver; Configuration Clusters).
     *
     * @param string $key A truncated version of the server's remote access key.
     * @param string $name The remote configuration cluster server's name.
     * @param string $user The username for the server's `root`-level account.
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/configuration-clusters/clusterserver-add_configclusterserver
     */
    public function addConfigClusterServer(
        #[SensitiveParameter]
        string $key,
        string $name,
        string $user,
    ): void {
        ($this->run)(ServerSpec::ADD_CONFIGCLUSTERSERVER, ['key' => $key, 'name' => $name, 'user' => $user]);
    }

    /**
     * Update background process stopper.
     *
     * This function configures the server's background process killer.
     *
     * Documented: Available in cPanel and WHM 11 and later. Uses form POST with one request and no automatic retry or
     * rollback.
     *
     * Documented: Configures server process termination. processesToKill accepts one process name or a nonempty
     * sequential string list, sent as repeated processes_to_kill keys. trustedUsers uses repeated trusted_users keys.
     * The source permits duplicates or incremented names. Omitting trustedUsers affects all users; process arguments
     * are sensitive command text.
     *
     * API-map identity: whm1:configurebackgroundprocesskiller#GET (wire name configurebackgroundprocesskiller;
     * Services).
     *
     * @param string|list<string> $processesToKill A process to kill in the `/usr/local/cpanel/etc/sym` directory.
     * @param string|list<string>|null $trustedUsers Unaffected users. Null omits it.
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @throws InvalidArgumentException If a list argument is empty or contains non-strings.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/services/sys-configurebackgroundprocesskiller
     */
    public function configureBackgroundProcessKiller(
        #[SensitiveParameter]
