     * @throws PayloadMismatchException If the API envelope reported success but the payload differs from the contract;
     *     the operation may already have changed state; do not retry automatically.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/updates/cpanel-start_cpanel_update
     */
    public function startCpanelUpdate(?string $mode = null): array
    {
        /** @var StartCpanelUpdateResult $result Validated against ServerSpec::START_CPANEL_UPDATE. */
        $result = ($this->run)(ServerSpec::START_CPANEL_UPDATE, ['mode' => $mode]);

        return $result;
    }

    /**
