    ): void {
        ($this->run)(ServerSpec::UPDATE_LINKED_SERVER_NODE, [
            'alias' => $alias,
            'apiToken' => $apiToken,
            'hostname' => $hostname,
            'skipTlsVerification' => $skipTlsVerification,
            'username' => $username,
        ]);
    }

    /**
     * Update software update behavior.
     *
     * This function modifies a server's `/etc/cpupdate.conf` file. This file controls how the server handles software
     * updates and upgrades.
     *
     * Documented: Available in cPanel and WHM 11.38 and later. Uses form POST with one request and no automatic retry
     * or rollback.
     *
     * Documented: Requires the root-level ACL and changes /etc/cpupdate.conf. All omitted fields retain existing
     * settings. SECURITY_UPDATES is independent of UPDATES and can apply current-major security updates hourly even
     * when UPDATES is manual or never. When RPMUP or SARULESUP is never, the administrator must run
     * /usr/local/cpanel/scripts/update-packages when updating system packages or SpamAssassin rules, respectively; the
     * client does not run that script. Freeform configuration values are sensitive.
     *
     * API-map identity: whm1:update_updateconf#POST (wire name update_updateconf; Updates).
     *
     * @param string|null $cpanel The cPanel & WHM installation's release tier, or a valid version number. Null omits
     *     it.
     * @param string|null $rpmup The frequency with which the server updates the operating system distribution's
     *     packages each time that the `/usr/local/cpanel/scripts/upcp` script runs. Null omits it.
     * @param string|null $sarulesup The frequency with which the server updates Apache SpamAssassin's™ rules when the
     *     `/usr/local/cpanel/scripts/upcp` script runs. Null omits it.
     * @param string|null $securityUpdates Whether the system applies expedited security updates for the current major
     *     version. Null omits it.
     * @param string|null $stagingDir The absolute directory path to the staging directory for updates. Null omits it.
     * @param string|null $updates When the system will check for updates. Null omits it.
     * @throws ApiException If transport, HTTP, the API envelope outcome, or payload validation fails.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/updates/cpupdate-update_updateconf
     */
    public function updateUpdateconf(
        #[SensitiveParameter]
        ?string $cpanel = null,
        #[SensitiveParameter]
        ?string $rpmup = null,
        #[SensitiveParameter]
        ?string $sarulesup = null,
        #[SensitiveParameter]
        ?string $securityUpdates = null,
        #[SensitiveParameter]
        ?string $stagingDir = null,
        #[SensitiveParameter]
        ?string $updates = null,
    ): void {
        ($this->run)(ServerSpec::UPDATE_UPDATECONF, [
            'cpanel' => $cpanel,
            'rpmup' => $rpmup,
            'sarulesup' => $sarulesup,
            'securityUpdates' => $securityUpdates,
            'stagingDir' => $stagingDir,
            'updates' => $updates,
        ]);
    }

